select.if:
select * from (
SELECT B.BOOKSET_ID as prodId, /**--账套代码**/ C.BOOKSET_NAME as prodName, /**--账套名称 **/ to_char(D.MDATE,'yyyy-mm-dd') as mDate, /**--到期日**/ NVL(T1.FINPROD_TYPE,T2.FINPROD_TYPE) AS finprodType, /**--资产类型**/ A.BUSI_ID as finprodId, /**--资产代码**/ NVL(T1.FINPROD_NAME,T2.FINPROD_ID) AS finprodName , /**--资产名称**/ A.SUBJECT_NO as subjectNo, /**--异常科目代码**/ E.SUBJECT_NAME as subjectName,/** --异常科目名称 **/ CASE WHEN SUM(DECODE(A.CD_FLAG, 'D', 1, -1) * A.HAPPEN_AMT) > 0 THEN 'D' ELSE 'C' END as balFlag, --余额方向 ABS(SUM(DECODE(A.CD_FLAG, 'D', 1, -1) * A.HAPPEN_AMT)) AS oAmt /**--科目余额 **/ FROM BOK_VOUCH_DETAIL A JOIN BOK_VOUCH_MAIN B ON A.VOUCH_NUM = B.VOUCH_NUM JOIN BOK_BOOKSET C ON B.BOOKSET_ID = C.BOOKSET_ID JOIN FIN_PRODUCT D ON C.ACCT_SUBJECT_ID = D.FINPROD_ID JOIN BOK_SUBJECT E ON A.SUBJECT_NO = E.SUBJECT_NO LEFT JOIN FIN_PRODUCT T1 ON A.BUSI_ID = T1.FINPROD_ID LEFT JOIN FIN_TRADE_PRODUCT T2 ON A.BUSI_ID = T2.FINPROD_ID
WHERE E.BASE_SUBJECT_NATURE IN
#{subject}
AND A.HAPPEN_DATE <= to_date(#{qrydate},'yyyy-MM-dd') AND D.MDATE >= to_date(#{qrydate},'yyyy-MM-dd')
AND B.BOOKSET_ID =#{queryDto.booksetId}
AND A.BUSI_ID IN
null) or A.BUSI_ID in (
#{assets}
and A.BUSI_ID not IN
#{noNull}
AND NVL(T1.FINPROD_TYPE,T2.FINPROD_TYPE) IN
#{fintype}
GROUP BY B.BOOKSET_ID, C.BOOKSET_NAME, D.MDATE, T1.FINPROD_TYPE, T2.FINPROD_TYPE, A.BUSI_ID, A.SUBJECT_NO, E.SUBJECT_NAME, T1.FINPROD_NAME, T2.FINPROD_ID HAVING SUM(DECODE(A.CD_FLAG, 'D', 1, -1) * A.HAPPEN_AMT) != 0
)

mapper.select:
SELECT B.BOOKSET_ID as prodId, /**--账套代码**/ C.BOOKSET_NAME as prodName, /**--账套名称 **/ to_char(D.MDATE,'yyyy-mm-dd') as mDate, /**--到期日**/ NVL(T1.FINPROD_TYPE,T2.FINPROD_TYPE) AS finprodType, /**--资产类型**/ A.BUSI_ID as finprodId, /**--资产代码**/ NVL(T1.FINPROD_NAME,T2.FINPROD_ID) AS finprodName , /**--资产名称**/ A.SUBJECT_NO as subjectNo, /**--异常科目代码**/ E.SUBJECT_NAME as subjectName,/** --异常科目名称 **/ CASE WHEN SUM(DECODE(A.CD_FLAG, 'D', 1, -1) * A.HAPPEN_AMT) > 0 THEN 'D' ELSE 'C' END as balFlag, --余额方向 ABS(SUM(DECODE(A.CD_FLAG, 'D', 1, -1) * A.HAPPEN_AMT)) AS oAmt /**--科目余额 **/ FROM BOK_VOUCH_DETAIL A JOIN BOK_VOUCH_MAIN B ON A.VOUCH_NUM = B.VOUCH_NUM JOIN BOK_BOOKSET C ON B.BOOKSET_ID = C.BOOKSET_ID JOIN FIN_PRODUCT D ON C.ACCT_SUBJECT_ID = D.FINPROD_ID JOIN BOK_SUBJECT E ON A.SUBJECT_NO = E.SUBJECT_NO and e.bookset_id=c.bookset_id_tmpl LEFT JOIN FIN_PRODUCT T1 ON A.BUSI_ID = T1.FINPROD_ID LEFT JOIN FIN_TRADE_PRODUCT T2 ON A.BUSI_ID = T2.FINPROD_ID WHERE E.BASE_SUBJECT_NATURE IN
#{subject}
AND A.HAPPEN_DATE <= to_date(#{qrydate},'yyyy-MM-dd') AND D.MDATE >= to_date(#{qrydate},'yyyy-MM-dd') AND B.BOOKSET_ID =#{booksetId} AND A.BUSI_ID IN
#{assets}
and A.BUSI_ID not IN
#{noNull}
AND NVL(T1.FINPROD_TYPE,T2.FINPROD_TYPE) IN
#{fintype}
GROUP BY B.BOOKSET_ID, C.BOOKSET_NAME, D.MDATE, T1.FINPROD_TYPE, T2.FINPROD_TYPE, A.BUSI_ID, A.SUBJECT_NO, E.SUBJECT_NAME, T1.FINPROD_NAME, T2.FINPROD_ID HAVING SUM(DECODE(A.CD_FLAG, 'D', 1, -1) * A.HAPPEN_AMT) != 0

SELECT B.BOOKSET_ID, A.BUSI_ID FROM BOK_VOUCH_DETAIL A JOIN BOK_VOUCH_MAIN B ON A.VOUCH_NUM = B.VOUCH_NUM JOIN BOK_BOOKSET C ON B.BOOKSET_ID = C.BOOKSET_ID JOIN FIN_PRODUCT D ON C.ACCT_SUBJECT_ID = D.FINPROD_ID AND D.FINPROD_TYPE = 'F16' AND D.MDATE >= to_date(#{qrydate},'yyyy-MM-dd') /**取产品信息获取到期日过滤出存续产品**/ JOIN FIN_PRODUCT T1 /**--标的类金融产品**/ ON A.BUSI_ID = T1.FINPROD_ID AND T1.FINPROD_TYPE IN
#{finprodtype}
JOIN TRD_PRODUCT_DEAL T2 /** --金融产品交易表**/ ON B.TRADE_ID = T2.TRADE_ID AND T2.FINPROD_TYPE IN
#{finprodtype}
JOIN BOK_SUBJECT E ON A.SUBJECT_NO = E.SUBJECT_NO and e.bookset_id=c.bookset_id_tmpl WHERE E.BASE_SUBJECT_NATURE IN
#{subjectNature}
AND A.HAPPEN_DATE <= to_date(#{qrydate},'yyyy-MM-dd')
AND B.BOOKSET_ID IN
#{booksetId}
GROUP BY B.BOOKSET_ID, A.BUSI_ID HAVING SUM(DECODE(A.CD_FLAG, 'D', 1, -1) * A.HAPPEN_AMT) <= 0

SELECT B.BOOKSET_ID, A.BUSI_ID FROM BOK_VOUCH_DETAIL A JOIN BOK_VOUCH_MAIN B ON A.VOUCH_NUM = B.VOUCH_NUM JOIN BOK_BOOKSET C ON B.BOOKSET_ID = C.BOOKSET_ID JOIN FIN_PRODUCT D ON C.ACCT_SUBJECT_ID = D.FINPROD_ID AND D.FINPROD_TYPE = 'F16'
AND D.MDATE >= to_date(#{qrydate},'yyyy-MM-dd') /**
--取产品信息获取到期日过滤出存续产品**/ LEFT JOIN FIN_PRODUCT T1 ON A.BUSI_ID = T1.FINPROD_ID LEFT JOIN FIN_TRADE_PRODUCT T2 ON A.BUSI_ID = T2.FINPROD_ID /**--T1\T2取资产信息,不在标的类金融产品则在交易类金融产品表 **/ JOIN BOK_SUBJECT E ON A.SUBJECT_NO = E.SUBJECT_NO and e.bookset_id=c.bookset_id_tmpl WHERE E.BASE_SUBJECT_NATURE IN
#{subjectNature}
AND A.HAPPEN_DATE <= to_date(#{qrydate},'yyyy-MM-dd')
AND B.BOOKSET_ID IN
#{booksetId}
AND NVL(T1.FINPROD_TYPE,T2.FINPROD_TYPE) IN
#{finprodtype}
GROUP BY B.BOOKSET_ID, A.BUSI_ID,A.HAPPEN_AMT HAVING SUM(DECODE(A.CD_FLAG, 'D', 1, -1) * A.HAPPEN_AMT) = 0
